pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EBU} from "../src/EBU.sol";

contract InvMutTest is Test {
    EBU c;

    function setUp() public {
        c = new EBU();
    }

    function testFuzz_property(
        address from,
        address[] memory _tos,
        uint256[] memory v
    ) public {
        vm.assume(_tos.length > 0);
        vm.assume(_tos.length == v.length);

        TokenHelper token = new TokenHelper();
        address caddress = address(token);

        bool cReturn = c.transfer(from, caddress, _tos, v);

        assertTrue(token.callCounter() == 0);
    }
}

contract TokenHelper {
    uint256 public callCounter;

    function transferFrom(address, address, uint256) external returns (bool) {
        revert("transferFrom not supported");
    }

    function transfer(address, uint256) external returns (bool) {
        callCounter++;
        return true;
    }
}
